import SeriesModel from '../src/model/Series';
import SeriesData from '../src/data/SeriesData';

describe('linked-data-npe', function () {

    function makeSeriesModelWithTaskData(taskData: SeriesData): SeriesModel {
        const seriesModel = new SeriesModel();
        seriesModel.init({}, null, {
            scheduler: {
                getPipeline: function () {
                    return {
                        currentTask: {
                            context: { data: taskData }
                        }
                    };
                }
            }
        } as any, {});
        return seriesModel;
    }

    it('getData(dataType) should not throw when data has no linked data', function () {
        // A plain SeriesData never linked via linkSeriesData has no
        // `getLinkedData` method (e.g. graph on cartesian2d, see #19900).
        const plainData = new SeriesData(null, null);
        const seriesModel = makeSeriesModelWithTaskData(plainData);

        expect(function () {
            expect(seriesModel.getData('edge' as any)).toBe(plainData);
        }).not.toThrow();
    });

    it('getData(dataType) should still consult linked data when present', function () {
        const mainData = new SeriesData(null, null);
        const edgeData = new SeriesData(null, null);
        mainData.getLinkedData = function (dataType: any) {
            return dataType === 'edge' ? edgeData : mainData;
        };
        const seriesModel = makeSeriesModelWithTaskData(mainData);

        expect(seriesModel.getData('edge' as any)).toBe(edgeData);
        expect(seriesModel.getData()).toBe(mainData);
    });
});

